	printf("&xv[0]=%p\n",&xv[0]);
	printf("&xv[13823]=%p\n",&xv[13823]);

	int i , j , numelems ;
	i        = localNumberOfRows-1   ;
	numelems = nonzerosInRow[i]      ;
	j        = mtxIndL[i][numelems-1];
	printf("Last Elem matrixValues[%d][%d] =%lf\n",localNumberOfRows-1,mtxIndL[i-1][j-1],matrixValues[i-1][j-1]);
	printf("&matrixValues[0][0]=%p\n",&matrixValues[0][0]);
	printf("&matrixValues[n-1][j-1]=%p\n",&matrixValues[i-1][j-1]);
	printf("&mtxIndL[0][0]=%p\n",&mtxIndL[0][0]);
	printf("&mtxIndL[n-1][j-1]=%p\n",&mtxIndL[i-1][j-1]);
	printf("Vector  x Size = %d*1\n",localNumberOfColumns);
	printf("xv[0]=%lf\n",xv[0]);
	printf("xv[m-1]=%lf\n",xv[localNumberOfColumns-1]);
	printf("yv[0]=%lf\n",yv[0]);
